'use client';

import { useState, useEffect } from 'react';

export default function UsersPage() {
  const [users, setUsers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
     const router = useRouter();
    const token=localStorage.getItem('token');
    if (!token) {
      setError('You must be logged in to view users.');
     router.push('/login');
      return;
    }
    const fetchUsers = async () => {
      try {
        const res = await fetch('http://localhost:8080/api/users'); // Update URL to match your API endpoint
        if (!res.ok) throw new Error('Failed to fetch users');
        const data = await res.json();
        setUsers(data);
      } catch (err) {
        setError(err.message);
      } finally {
        setLoading(false);
      }
    };

    fetchUsers();
  }, []);

  if (loading) return <div className="p-8 text-center text-sm text-gray-500">Loading users...</div>;
  if (error) return <div className="p-8 text-center text-sm text-red-500">Error: {error}</div>;

  return (
    <div className="max-w-3xl mx-auto p-6">
      <h1 className="text-2xl font-bold mb-6 text-gray-900">Users List</h1>

      <div className="grid gap-4 sm:grid-cols-2">
        {users.map((user) => (
          <div
            key={user._id}
            className="border rounded-lg p-4 bg-white shadow-sm hover:shadow-md transition-shadow"
          >
            <h2 className="font-semibold text-lg text-gray-800">{user.name}</h2>
            <p className="text-sm text-gray-600 mb-2">{user.email}</p>
            <p className="text-xs text-gray-400">
              Joined: {new Date(user.createdAt).toLocaleDateString()}
            </p>
          </div>
        ))}
      </div>
    </div>
  );
}